CREATE TABLE `UpcomingRelease` (
 `id` VARCHAR(191) NOT NULL, `type` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `subtitle` VARCHAR(191) NULL, `imageUrl` VARCHAR(191) NULL, `mediaPath` TEXT NULL, `availableAt` DATETIME(3) NOT NULL, `publishAt` DATETIME(3) NULL, `seasonNumber` INTEGER NULL, `episodeNumber` INTEGER NULL, `enabled` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
